export const protocolVersion = 1;

export function pageAfter(items, cursor, limit) {
  if (!Number.isInteger(limit) || limit < 1 || limit > 100) {
    throw new RangeError('limit must be an integer between 1 and 100');
  }

  if (cursor === null || cursor === undefined) {
    return sliceFrom(items, limit, 0);
  }

  let start = -1;
  for (let i = 0; i < items.length; i++) {
    if (items[i].id === cursor) {
      start = i + 1;
      break;
    }
  }

  if (start === -1) {
    throw new RangeError('unknown cursor: ' + cursor);
  }

  return sliceFrom(items, limit, start);
}

function sliceFrom(items, limit, start) {
  const page = [];
  for (let i = start; i < items.length && page.length < limit; i++) {
    page.push(items[i]);
  }

  const more = start + page.length < items.length;
  return {
    items: page,
    nextCursor: more ? page[page.length - 1].id : null,
  };
}

